/* ---------- Leogrow Business · C1 units (format: see biz_b1.js) ---------- */
var BIZ_UNITS_SRC=(typeof BIZ_UNITS_SRC!=='undefined'&&BIZ_UNITS_SRC)||[];
BIZ_UNITS_SRC.push(
/* ================= C1 · 9 Persuasion and Pitching ================= */
{id:"bz9",level:"C1",title:"Persuasion and Pitching",sub:"Hooking an audience, building an argument, handling objections and closing a pitch with a clear call to action.",subPl:"Przyciąganie uwagi, budowanie argumentacji, odpowiadanie na zastrzeżenia i zamykanie prezentacji wezwaniem do działania.",
 lessons:[
 {t:"Hooking your audience",intro:"The first 30 seconds decide whether people listen. Questions, surprising facts and short stories.",
  sample:{h:"Opening of an investor pitch",text:"[[QUESTION|How many hours did you spend on email last week?]] [[FACT|According to a recent study]], the average manager spends 11 hours a week in their inbox — [[FACT|that's more than a quarter of the working week]].\n\n[[STORY|Two years ago, our team was in exactly the same situation.]] [[PROBLEM|The real problem isn't email itself — it's]] the lack of priorities.\n\n[[PROMISE|In the next ten minutes, I'll show you how]] our tool gives managers back five hours a week."},
  groups:[["Ways to open",[
   ["QUESTION","How many of you have ever …?","Gets the audience involved.","Ilu z Państwa kiedykolwiek …?"],
   ["QUESTION","Imagine for a moment that …","Creates a picture.","Wyobraźmy sobie przez chwilę, że …"],
   ["FACT","According to a recent study, …","Credible surprising fact.","Według niedawnego badania …"],
   ["FACT","Here's a figure that may surprise you: …","Builds curiosity.","Oto liczba, która może Państwa zaskoczyć: …"],
   ["STORY","Let me tell you a quick story.","Personal, memorable opening.","Pozwólcie, że opowiem krótką historię."],
   ["STORY","Two years ago, we were exactly where you are now.","Identification with the audience.","Dwa lata temu byliśmy dokładnie tam, gdzie Państwo teraz."]]],
  ["Framing the problem and the promise",[
   ["PROBLEM","The real problem isn't …, it's …","Reframes the issue.","Prawdziwym problemem nie jest …, tylko …"],
   ["PROBLEM","What most people don't realise is that …","Creates insight.","Większość ludzi nie zdaje sobie sprawy, że …"],
   ["STAKES","If nothing changes, …","Shows the cost of inaction.","Jeśli nic się nie zmieni, …"],
   ["PROMISE","In the next ten minutes, I'll show you how …","Clear promise.","W ciągu najbliższych dziesięciu minut pokażę, jak …"],
   ["PROMISE","By the end of this talk, you'll know exactly …","Sets expectations.","Pod koniec tego wystąpienia będą Państwo dokładnie wiedzieć …"]]]],
  note:{h:"Rhetorical devices that persuade",html:`<p><b>Rule of three:</b> “It's faster, cheaper and safer.” — three items feel complete.</p><p><b>Contrast:</b> “It's not about working harder; it's about working smarter.”</p><p><b>Rhetorical question:</b> “So what does this mean for us?” — you answer it yourself.</p><p><b>Concrete numbers:</b> “five hours a week” beats “a lot of time”.</p><div class="bz-box tip">Cut the weak openings: <i>“So, um, today I'm going to talk about…”</i> Start with the hook, then introduce yourself.</div>`},
  mc:[["Which opening hooks the audience best?","How many of you checked your email before breakfast today?","Hello, my name is Tom and this is my presentation.","So, um, let's start, I guess.",0],
   ["You introduce a surprising, credible fact:","According to a recent study, 60% of projects run over budget.","Everybody knows projects are bad.","I heard somewhere that projects fail.",0],
   ["You reframe the problem:","The real problem isn't the price, it's the hidden costs.","Problem is price, also costs.","The price is a problem not.",0],
   ["Which is an example of the rule of three?","It's faster, cheaper and safer.","It's faster.","It's faster and faster and faster and cheaper and good.",0],
   ["You show the cost of doing nothing:","If nothing changes, we'll lose our biggest client within a year.","Maybe something happens.","Nothing will change, it's fine.",0],
   ["A clear promise to the audience:","In the next ten minutes, I'll show you how to cut costs by 20%.","I will talk some time about costs.","Costs are interesting, let's see.",0],
   ["Which uses contrast?","It's not about working harder; it's about working smarter.","Working is hard and smart.","Hard work is good work.",0],
   ["Which phrase creates insight?","What most people don't realise is that churn costs five times more than acquisition.","People realise many things.","Most people are not realising.",0]],
  bank:{h:"Complete the pitch opening",text:"{Imagine for a moment that} your warehouse never runs out of stock. {Here's a figure that may surprise you}: retailers lose 4% of sales every year because of empty shelves. {What most people don't realise is that} the data to prevent this already exists. {The real problem isn't} the data, {it's} how slowly we use it. {If nothing changes}, that 4% will keep growing. {In the next ten minutes, I'll show you how} our forecasting tool fixes this — {faster, cheaper and safer} than any system you use today.",extra:["So, um","Let me tell you a quick story"]}},
 {t:"Building the argument and handling objections",intro:"Back up your claims, concede smartly and answer tough objections without losing control.",
  groups:[["Supporting your case",[
   ["EVIDENCE","The evidence clearly shows that …","Strong, data-based claim.","Dowody jasno pokazują, że …"],
   ["EVIDENCE","Take, for example, …","Introduces a concrete case.","Weźmy na przykład …"],
   ["EVIDENCE","This is borne out by …","Formal: confirmed by.","Potwierdza to …"],
   ["BENEFIT","What this means for you is …","Translates features into benefits.","Dla Państwa oznacza to …"],
   ["BENEFIT","Not only …, but also …","Adds a second advantage (note inversion).","Nie tylko …, ale również …"],
   ["CONCEDE","Admittedly, …, but …","Concede a weak point, then win it back.","Co prawda …, ale …"]]],
  ["Handling objections",[
   ["ACK","I can see why you might think that.","Acknowledges without agreeing.","Rozumiem, dlaczego mogą Państwo tak sądzić."],
   ["ACK","That's a fair point.","Accepts a valid point.","To uczciwa uwaga."],
   ["REFRAME","Let me put it another way.","Reframes the argument.","Ujmę to inaczej."],
   ["REFRAME","If we look at the bigger picture, …","Shifts focus.","Jeśli spojrzymy szerzej, …"],
   ["COUNTER","That may be true in the short term, however …","Counters with a longer view.","To może być prawda w krótkim okresie, jednak …"],
   ["PROBE","What specifically concerns you about …?","Finds the real objection.","Co konkretnie Państwa niepokoi w …?"]]]],
  note:{h:"Inversion for emphasis",html:`<p>After negative or limiting words at the start, use question word order — it sounds strong and formal.</p><p class="ok">✓ <b>Not only does</b> it save time, but it also reduces errors.</p><p class="ok">✓ <b>Never have we</b> seen such strong demand.</p><p class="ok">✓ <b>Only by</b> acting now <b>can we</b> keep our market share.</p><p class="no">✗ Not only it saves time, but also…</p>`},
  mc:[["Which is correct?","Not only does it cut costs, but it also improves quality.","Not only it cuts costs, but also it improves quality.","Not only cuts it costs, but improves also quality.",0],
   ["A client says your product is too expensive. You acknowledge:","I can see why you might think that.","You're wrong about the price.","Everything is expensive now.",0],
   ["You concede a weakness and then win back:","Admittedly, the set-up takes a week, but after that it runs itself.","The set-up is long, sorry.","Set-up is a week. Bye.",0],
   ["You want to find the real objection:","What specifically concerns you about the migration?","Why don't you like it?","You are worried, why?",0],
   ["You translate a feature into a benefit:","What this means for you is two fewer days of reporting each month.","It has a dashboard.","Our dashboard is blue.",0],
   ["You counter with a long-term view:","That may be true in the short term, however the savings appear within six months.","No, that's not true at all.","Short term is not important ever.",0],
   ["You introduce a concrete case:","Take, for example, our project with Orlen.","For example take Orlen project.","Example: Orlen.",0],
   ["Which is correct?","Only by investing now can we stay competitive.","Only by investing now we can stay competitive.","Only investing now can stay we competitive.",0]],
  bank:{h:"Complete the answer to an objection",text:"Client: Honestly, your solution is 30% more expensive than the competition.\nYou: {That's a fair point}, and {I can see why you might think that}. {Let me put it another way}. {Admittedly}, the licence costs more, {but} the maintenance is included. {Take, for example}, our client in Łódź: they cut IT costs by 18% in the first year. {Not only does} it reduce costs, but it also saves your team about ten hours a month. {If we look at the bigger picture}, the total cost is actually lower. {What specifically concerns you about} the price — the budget this year, or the total over three years?",extra:["You're wrong","Not only it"]}},
 {t:"Closing with a call to action",intro:"End strong: summarise, make the ask and make it easy for people to say yes.",
  groups:[["Ending strong",[
   ["RECAP","So, to bring it all together, …","Final summary.","Podsumowując wszystko, …"],
   ["RECAP","If you remember one thing from today, let it be this: …","Single key message.","Jeśli mają Państwo zapamiętać z dzisiaj jedno, niech to będzie: …"],
   ["CALL","What I'm asking you to do today is …","Clear ask.","Proszę Państwa dziś o …"],
   ["CALL","The next step would be to …","Small, easy next step.","Następnym krokiem byłoby …"],
   ["CALL","I'd like to propose that we start with a pilot.","Lowers the risk.","Proponuję, żebyśmy zaczęli od pilotażu."]]],
  ["Making it easy to say yes",[
   ["RISK","There's no long-term commitment.","Removes risk.","Nie ma długoterminowego zobowiązania."],
   ["RISK","If it doesn't deliver results, you can cancel at any time.","Guarantee.","Jeśli nie przyniesie efektów, mogą Państwo zrezygnować w każdej chwili."],
   ["URGENCY","The sooner we start, the sooner you'll see the savings.","Gentle urgency.","Im szybciej zaczniemy, tym szybciej zobaczą Państwo oszczędności."],
   ["URGENCY","This offer is valid until the end of the quarter.","Time-limited.","Oferta jest ważna do końca kwartału."],
   ["VISION","Picture where your team could be a year from now.","Ends with a vision.","Wyobraźcie sobie, gdzie Wasz zespół może być za rok."],
   ["THANK","Thank you — I'm happy to take your questions.","Final line.","Dziękuję — chętnie odpowiem na pytania."]]]],
  mc:[["A strong final summary line:","If you remember one thing from today, let it be this: data beats guesswork.","So, that's all, I think.","OK, I'm finished now.",0],
   ["A clear call to action:","What I'm asking you to do today is approve a three-month pilot.","Maybe you could think about something.","Do what you want.",0],
   ["You lower the risk for the client:","There's no long-term commitment.","You must sign for five years.","Risk is your problem.",0],
   ["Gentle urgency:","The sooner we start, the sooner you'll see the savings.","Start now or lose everything!","Hurry, hurry!",0],
   ["You suggest a small first step:","The next step would be to run a pilot in one department.","Next, buy everything.","Next step is big.",0],
   ["Which ending sounds weakest?","So, um, yeah, that's it.","Picture where your team could be a year from now.","Thank you — I'm happy to take your questions.",0],
   ["You offer a guarantee:","If it doesn't deliver results, you can cancel at any time.","It always works, trust me.","No guarantees, sorry.",0],
   ["You bring the main ideas together:","So, to bring it all together, …","So, to bring all it together, …","Bringing together it all, …",0]],
  bank:{h:"Complete the close of the pitch",text:"{So, to bring it all together}: you lose 4% of sales to empty shelves, and our tool can cut that in half. {If you remember one thing from today, let it be this}: the data is already in your system. {What I'm asking you to do today is} to try it. {I'd like to propose that we start with a pilot} in five stores. {There's no long-term commitment}, and {if it doesn't deliver results, you can cancel at any time}. {The sooner we start, the sooner you'll see the savings}. {Thank you — I'm happy to take your questions}.",extra:["So, um, yeah"]},
  task:{kind:"speak",h:"Give a 2-minute pitch",intro:"Pitch a product, a service or an internal idea to decision-makers. Record it and check it against the list.",
   steps:[["Hook","A question, a surprising figure or a short story."],["Problem and stakes","“The real problem isn't…, it's…” / “If nothing changes, …”"],["Promise and solution","“In the next two minutes, I'll show you how…”"],["Evidence and benefit","“Take, for example, …” / “What this means for you is …”"],["Handle one objection","“Admittedly, …, but …”"],["Call to action","“What I'm asking you to do today is …” / “The next step would be to …”"]],
   topics:["A four-day working week pilot in your team","A new app for your company's customers","Moving your team to a new project tool","Investing in English training for all staff"],
   check:["I started with a hook, not with my name.","I used at least one rhetorical device (rule of three, contrast, question).","I gave a concrete number or example.","I used one inversion (Not only does… / Only by…).","My call to action was specific and easy to accept.","I stayed under 2.5 minutes."]}}
 ]},

/* ================= C1 · 10 Reports and Proposals ================= */
{id:"bz10",level:"C1",title:"Reports and Proposals",sub:"Formal structure and register, hedging and impersonal language, and writing clear recommendations.",subPl:"Formalna struktura i rejestr, łagodzenie stwierdzeń i język bezosobowy, pisanie jasnych rekomendacji.",
 lessons:[
 {t:"Structure and formal register",intro:"How a business report is organised and how to write in a formal, neutral style.",
  groups:[["Signposting a report",[
   ["AIM","The aim of this report is to …","Opening of the introduction.","Celem niniejszego raportu jest …"],
   ["AIM","This report examines / assesses …","Alternative opening.","Niniejszy raport analizuje / ocenia …"],
   ["METHOD","The findings are based on …","Explains the sources.","Wnioski opierają się na …"],
   ["FINDINGS","It was found that …","Impersonal finding.","Stwierdzono, że …"],
   ["FINDINGS","The majority of respondents …","Survey results.","Większość respondentów …"],
   ["CONCLUDE","In light of these findings, …","Moves to conclusions.","W świetle tych ustaleń …"]]],
  ["Formal equivalents",[
   ["FORMAL","obtain (= get)","We obtained data from 300 users.","uzyskać"],
   ["FORMAL","require (= need)","The project requires additional funding.","wymagać"],
   ["FORMAL","approximately (= about)","approximately 40% of staff","w przybliżeniu"],
   ["FORMAL","however (= but)","Sales rose. However, profits fell.","jednak"],
   ["FORMAL","in addition / furthermore (= also)","Furthermore, costs decreased.","ponadto"],
   ["FORMAL","prior to (= before)","prior to the launch","przed"]]]],
  note:{h:"The standard report structure",html:`<table><tr><th>Section</th><th>Content</th></tr><tr><td>Introduction</td><td>aim, scope, method</td></tr><tr><td>Findings</td><td>facts and data, usually with headings and numbers</td></tr><tr><td>Conclusions</td><td>what the findings mean</td></tr><tr><td>Recommendations</td><td>what should be done</td></tr></table><p><b>Formal register:</b> no contractions (<i>do not</i>, not <i>don't</i>), no phrasal verbs where a single verb exists (<i>investigate</i>, not <i>look into</i>), no “I think”.</p>`},
  mc:[["The best first sentence of a report:","The aim of this report is to assess staff satisfaction with remote work.","Hi, this report is about remote work.","I want to tell you about remote work.",0],
   ["Formal version of 'get':","obtain","grab","pick up",0],
   ["Which sentence is in formal register?","The project requires additional funding.","The project needs more cash.","We gotta get more money for the project.",0],
   ["Impersonal way to present a finding:","It was found that most staff prefer hybrid work.","I found out that people like hybrid.","We think staff like hybrid, maybe.",0],
   ["Which word links two contrasting sentences formally?","However,","But,","Anyway,",0],
   ["Formal version of 'before':","prior to","ahead","before of",0],
   ["Which section says what should be done?","Recommendations","Introduction","Findings",0],
   ["Which avoids a contraction?","The system does not support mobile devices.","The system doesn't support mobile devices.","The system won't support mobiles.",0]],
  bank:{h:"Complete the report introduction",text:"{The aim of this report is to} assess the results of the hybrid working pilot. {The findings are based on} a survey of 240 employees and data {obtained} from the HR system. {It was found that} productivity remained stable. {The majority of respondents} reported a better work–life balance. {However}, {approximately} 30% felt less connected to their team. {Furthermore}, office costs fell by 18%. {In light of these findings}, the following recommendations are made.",extra:["I think","doesn't"]},
  order:{h:"Put the report sections in order",items:["Introduction: aim, scope and method","Findings: survey results and data","Conclusions: what the results mean","Recommendations: what should be done next"]}},
 {t:"Hedging and impersonal language",intro:"Sound careful and objective: soften claims, use the passive and avoid overstating.",
  groups:[["Hedging",[
   ["HEDGE","It would appear that …","Very careful claim.","Wydawałoby się, że …"],
   ["HEDGE","This may / might / could indicate …","Modal verbs soften.","Może to wskazywać na …"],
   ["HEDGE","… is likely to …","Probable result.","… prawdopodobnie …"],
   ["HEDGE","There is some evidence to suggest that …","Cautious evidence.","Istnieją przesłanki sugerujące, że …"],
   ["HEDGE","to a certain extent","Partial truth.","w pewnym stopniu"],
   ["HEDGE","a significant proportion of …","Instead of 'lots of'.","znaczna część …"]]],
  ["Impersonal structures",[
   ["PASSIVE","It is recommended that …","No 'I' or 'we'.","Zaleca się, aby …"],
   ["PASSIVE","It has been suggested that …","Reports others' views.","Zasugerowano, że …"],
   ["PASSIVE","It is generally agreed that …","Shared view.","Powszechnie uważa się, że …"],
   ["PASSIVE","… are expected to …","Prediction.","Oczekuje się, że …"],
   ["NOUN","There has been a decline in …","Noun style instead of verbs.","Nastąpił spadek …"],
   ["NOUN","The implementation of … will require …","Formal noun phrase.","Wdrożenie … będzie wymagało …"]]]],
  note:{h:"From strong to careful",html:`<p>The new system <b>will</b> solve all our problems. <span class="no">(overstated)</span></p><p>The new system <b>is likely to</b> solve most of our problems. <span class="ok">(hedged)</span></p><p>The new system <b>could</b> help to solve some of our problems. <span class="ok">(very careful)</span></p><div class="bz-box">Hedging is not weakness — it shows you separate <b>facts</b> from <b>interpretation</b>. Readers trust it more.</div>`},
  mc:[["Which is most appropriately hedged?","The data would appear to suggest a drop in demand.","The data proves demand is dead.","Demand is obviously finished.",0],
   ["Impersonal recommendation:","It is recommended that the budget be reviewed.","I recommend you to review budget.","We say: review budget.",0],
   ["Instead of 'lots of employees' in a report:","a significant proportion of employees","loads of employees","a lot of guys",0],
   ["Probable future result:","Costs are likely to rise next year.","Costs rise surely next year.","Costs will rise 100%.",0],
   ["Noun style:","There has been a decline in customer satisfaction.","Customers are less happy now, sadly.","Satisfaction went down a lot.",0],
   ["Reporting other people's views:","It has been suggested that the deadline is unrealistic.","Somebody said deadline is bad.","They told the deadline is not real.",0],
   ["Partly true:","This is true to a certain extent.","This is true to certain extend.","This is a bit true kind of.",0],
   ["Which is correct?","It is recommended that each team appoint a coordinator.","It is recommended that each team appoints to a coordinator.","It recommends each team appointing coordinator.",0]],
  bank:{h:"Rewrite the findings in a careful style",text:"{There is some evidence to suggest that} remote workers are more productive. {It would appear that} meetings are shorter and better prepared. {However}, {a significant proportion of} new employees feel isolated, which {may indicate} a problem with onboarding. {There has been a decline in} informal knowledge sharing. Office costs {are likely to} fall further. {It has been suggested that} teams meet in person once a week. {It is recommended that} this is tested for three months.",extra:["proves that","loads of"]}},
 {t:"Writing recommendations and proposals",intro:"Recommend clearly, justify with evidence, and present costs, benefits and next steps.",
  groups:[["Recommending",[
   ["RECOMMEND","It is strongly recommended that …","Strong formal recommendation.","Zdecydowanie zaleca się, aby …"],
   ["RECOMMEND","The company should consider …","+ -ing: consider introducing …","Firma powinna rozważyć …"],
   ["RECOMMEND","A more effective approach would be to …","Compares options.","Skuteczniejszym podejściem byłoby …"],
   ["JUSTIFY","This would enable us to …","Shows the benefit.","Pozwoliłoby nam to …"],
   ["JUSTIFY","This is particularly important given that …","Links to evidence.","Jest to szczególnie ważne, biorąc pod uwagę, że …"]]],
  ["Costs, risks and next steps",[
   ["COST","The estimated cost is …","Gives the budget.","Szacunkowy koszt wynosi …"],
   ["COST","This would pay for itself within …","Return on investment.","Zwróciłoby się to w ciągu …"],
   ["RISK","The main risk is …, which could be mitigated by …","Risk + mitigation.","Głównym ryzykiem jest …, które można ograniczyć poprzez …"],
   ["NEXT","Subject to approval, the project could begin in …","Conditional start.","Po zatwierdzeniu projekt mógłby rozpocząć się w …"],
   ["NEXT","We propose a review after six months.","Plans an evaluation.","Proponujemy ocenę po sześciu miesiącach."],
   ["NEXT","Should you require further information, please …","Formal ending (inversion of 'If you should…').","W razie potrzeby dodatkowych informacji prosimy …"]]]],
  mc:[["A strong formal recommendation:","It is strongly recommended that the training be extended to all departments.","Training for all, please!","We think maybe training is good.",0],
   ["Which is correct?","The company should consider introducing flexible hours.","The company should consider to introduce flexible hours.","The company should consider introduce flexible hours.",0],
   ["You show a benefit:","This would enable us to reduce turnover.","This would enable to reduce us turnover.","This enables reducing for us turnover.",0],
   ["You mention a risk and how to reduce it:","The main risk is staff resistance, which could be mitigated by early communication.","Risk: people angry.","There is no risk at all.",0],
   ["Return on investment:","This would pay for itself within 18 months.","This pays itself in 18 months maybe.","It will repay us 18 months.",0],
   ["Formal ending of a proposal:","Should you require further information, please do not hesitate to contact me.","If you want more, write.","Questions? Call me!",0],
   ["You start the project only after a decision:","Subject to approval, the project could begin in September.","When you say yes we start September.","Approved or not, September.",0],
   ["You compare two options:","A more effective approach would be to outsource the service.","More effective is outsourcing better.","Outsource is the most better.",0]],
  bank:{h:"Complete the recommendations",text:"Recommendations\n\n1. {It is strongly recommended that} the hybrid model be made permanent. {This would enable us to} reduce office space by one floor. {The estimated cost is} €40,000 for new equipment, and {this would pay for itself within} one year.\n\n2. {The company should consider} introducing a buddy system for new employees. {This is particularly important given that} new staff report feeling isolated.\n\n3. {The main risk is} weaker team culture, {which could be mitigated by} a monthly team day. {We propose a review after six months}.\n\n{Should you require further information}, please contact the HR department.",extra:["should consider to"]},
  task:{kind:"write",min:150,h:"Write a short proposal",intro:"Your manager asked for a proposal (150–200 words) on one change in your company. Use headings: Aim, Findings, Recommendation, Cost and next steps.",
   steps:[["Aim","“The aim of this proposal is to …”"],["Findings","“It was found that … / There is some evidence to suggest that …”"],["Recommendation","“It is strongly recommended that … This would enable us to …”"],["Cost and risk","“The estimated cost is … The main risk is …, which could be mitigated by …”"],["Next steps","“Subject to approval, … We propose a review after …”"]],
   topics:["Introducing a four-day week for one team","Replacing business travel with video meetings","Paying for English lessons for all employees","Moving to a paperless office"],
   check:["I used headings.","I wrote no contractions and no 'I think'.","I hedged at least two claims.","I used at least two impersonal structures (It is recommended…).","I included a cost and a risk.","The proposal is 150–200 words."]}}
 ]},

/* ================= C1 · 11 Leading People ================= */
{id:"bz11",level:"C1",title:"Leading People",sub:"Giving and receiving feedback, delegating and motivating, and handling difficult conversations.",subPl:"Udzielanie i przyjmowanie informacji zwrotnej, delegowanie i motywowanie, trudne rozmowy.",
 lessons:[
 {t:"Giving feedback",intro:"Praise specifically, criticise constructively and agree on what will change.",
  sample:{h:"A feedback conversation",text:"[[OPEN|Have you got a few minutes? I'd like to give you some feedback]] on the client presentation.\n\n[[PRAISE|I was really impressed by]] how you handled the questions — [[PRAISE|that made a real difference]].\n\n[[DEVELOP|One thing I'd like you to work on is]] timing. [[FACT|When the presentation ran 15 minutes over]], [[IMPACT|the client had to leave before the Q&A]].\n\n[[ASK|How do you see it?]] … [[AGREE|So going forward, could you]] rehearse with a timer before big meetings?"},
  groups:[["Positive and developmental feedback",[
   ["OPEN","Have you got a few minutes? I'd like to give you some feedback.","Sets up the talk.","Masz kilka minut? Chciałbym/chciałabym przekazać Ci informację zwrotną."],
   ["PRAISE","I was really impressed by …","Specific praise.","Naprawdę zrobiło na mnie wrażenie …"],
   ["PRAISE","That made a real difference.","Shows the impact of good work.","To zrobiło prawdziwą różnicę."],
   ["DEVELOP","One thing I'd like you to work on is …","Constructive, forward-looking.","Jedna rzecz, nad którą chciałbym/chciałabym, żebyś popracował/a, to …"],
   ["FACT","When …, …","Describe the behaviour, not the person.","Kiedy …, …"],
   ["IMPACT","The effect of that was …","Explains consequences.","Skutkiem tego było …"]]],
  ["Dialogue and agreement",[
   ["ASK","How do you see it?","Invites their view.","Jak Ty to widzisz?"],
   ["ASK","What could you do differently next time?","Lets them find the solution.","Co mógłbyś/mogłabyś zrobić inaczej następnym razem?"],
   ["SUPPORT","What support do you need from me?","Offers help.","Jakiego wsparcia ode mnie potrzebujesz?"],
   ["AGREE","So going forward, could you …?","Agrees on change.","Czyli od teraz, czy mógłbyś/mogłabyś …?"],
   ["RECEIVE","Thanks, that's really useful to know.","Receiving feedback well.","Dzięki, to bardzo przydatne."],
   ["RECEIVE","Could you give me an example?","Asks for detail when receiving criticism.","Czy możesz podać przykład?"]]]],
  note:{h:"The SBI model: Situation, Behaviour, Impact",html:`<p><b>Situation:</b> “In yesterday's meeting with the client…”</p><p><b>Behaviour:</b> “…you interrupted them three times…” (what you saw — not “you're rude”)</p><p><b>Impact:</b> “…and they seemed frustrated.”</p><div class="bz-box warn">Avoid labels: <i>lazy, careless, unprofessional</i>. Describe actions instead. Avoid “always” and “never”.</div>`},
  mc:[["Specific praise:","I was really impressed by the way you structured the report.","Good job.","You're the best.",0],
   ["Which follows SBI (describes behaviour, not the person)?","In the meeting, you checked your phone several times, and the client noticed.","You're so unprofessional.","You never pay attention.",0],
   ["Constructive and forward-looking:","One thing I'd like you to work on is your timing.","Your timing is terrible.","Stop being late always.",0],
   ["You let the employee find the solution:","What could you do differently next time?","Do it my way.","Next time don't fail.",0],
   ["You offer help:","What support do you need from me?","Help yourself.","Don't ask me.",0],
   ["You receive criticism well:","Thanks, that's really useful to know. Could you give me an example?","That's not true.","Everyone does that.",0],
   ["Which word should you avoid in feedback?","always","specifically","example",0],
   ["You agree on the change:","So going forward, could you send the agenda a day before?","So you will never do it again, yes?","Fine, whatever.",0]],
  bank:{h:"Complete the feedback",text:"{Have you got a few minutes? I'd like to give you some feedback} on last week's project. {I was really impressed by} the quality of your analysis — {that made a real difference} to the client. {One thing I'd like you to work on is} updating the team. {When} the deadline changed, the team only found out on Friday. {The effect of that was} two people had to work at the weekend. {How do you see it}? … OK. {What support do you need from me}? {So going forward, could you} send a short update every Monday?",extra:["You're lazy","always"]}},
 {t:"Delegating and motivating",intro:"Hand over tasks clearly, give ownership and keep people motivated.",
  groups:[["Delegating",[
   ["ASSIGN","I'd like you to take the lead on …","Gives ownership.","Chciałbym/chciałabym, żebyś poprowadził/a …"],
   ["ASSIGN","Would you be willing to take on …?","Asks, not orders.","Czy byłbyś/byłabyś gotów/gotowa przejąć …?"],
   ["SCOPE","You'll have full responsibility for …","Clarifies authority.","Będziesz w pełni odpowiedzialny/a za …"],
   ["SCOPE","The key deliverable is …","What exactly must be produced.","Kluczowym rezultatem jest …"],
   ["DEADLINE","Could you have it ready by …?","Clear deadline.","Czy możesz to przygotować do …?"],
   ["CHECK","Let's touch base on Thursday to see how it's going.","Check-in, not control.","Spotkajmy się w czwartek, żeby zobaczyć, jak idzie."]]],
  ["Motivating",[
   ["TRUST","I chose you because …","Explains the trust.","Wybrałem/wybrałam Ciebie, ponieważ …"],
   ["TRUST","I trust your judgement on this.","Gives autonomy.","Ufam Twojej ocenie w tej sprawie."],
   ["GROWTH","This is a great opportunity to develop your …","Links to their growth.","To świetna okazja, by rozwinąć …"],
   ["PURPOSE","This matters because …","Gives meaning.","To ważne, ponieważ …"],
   ["RECOGNISE","I really appreciate the extra effort you've put in.","Recognition.","Naprawdę doceniam dodatkowy wysiłek, który włożyłeś/aś."],
   ["RECOGNISE","Your work on … hasn't gone unnoticed.","Formal recognition.","Twoja praca nad … nie przeszła bez echa."]]]],
  mc:[["You delegate and give ownership:","I'd like you to take the lead on the supplier audit.","Do the audit.","Audit is yours, good luck alone.",0],
   ["You ask rather than order:","Would you be willing to take on the training plan?","You will do the training plan.","Training plan, now.",0],
   ["You make the result clear:","The key deliverable is a two-page summary for the board.","Write something.","Make it nice.",0],
   ["A check-in that doesn't sound like control:","Let's touch base on Thursday to see how it's going.","I'll watch you every day.","Report every hour.",0],
   ["You give autonomy:","I trust your judgement on this.","Ask me before every decision.","Don't decide anything.",0],
   ["You link the task to growth:","This is a great opportunity to develop your leadership skills.","You have no choice.","Nobody else wanted it.",0],
   ["Recognition:","I really appreciate the extra effort you've put in.","Finally you did something.","It was your job anyway.",0],
   ["You give the task meaning:","This matters because the client renewal depends on it.","Just do it.","Because I said so.",0]],
  bank:{h:"Complete the delegation talk",text:"Kasia, {I'd like you to take the lead on} the new client onboarding. {I chose you because} you know the product better than anyone. {You'll have full responsibility for} the plan and the budget. {The key deliverable is} a step-by-step guide for the team. {Could you have it ready by} the end of the month? {This matters because} new clients often leave in the first 90 days. {This is a great opportunity to develop your} project management skills. {I trust your judgement on this}. {Let's touch base on Thursday to see how it's going}.",extra:["Because I said so"]}},
 {t:"Difficult conversations",intro:"Talk about poor performance, conflict or bad news — calmly, honestly and with respect.",
  groups:[["Opening and stating the issue",[
   ["OPEN","I wanted to talk to you about something that's been on my mind.","Gentle opening.","Chciałem/chciałam porozmawiać o czymś, co od jakiegoś czasu mnie zajmuje."],
   ["OPEN","This isn't an easy conversation, but it's an important one.","Names the difficulty.","To nie jest łatwa rozmowa, ale ważna."],
   ["ISSUE","I've noticed that …","Neutral observation.","Zauważyłem/zauważyłam, że …"],
   ["ISSUE","I'm concerned that …","States concern, not blame.","Niepokoi mnie, że …"],
   ["NEWS","I'm afraid I have some bad news.","Prepares for bad news.","Niestety mam złe wiadomości."],
   ["NEWS","I wanted you to hear it from me first.","Shows respect.","Chciałem/chciałam, żebyś usłyszał/a to najpierw ode mnie."]]],
  ["Listening and finding a way forward",[
   ["LISTEN","Help me understand what's been happening.","Invites their side.","Pomóż mi zrozumieć, co się dzieje."],
   ["LISTEN","It sounds like you're feeling …","Reflects emotions.","Wygląda na to, że czujesz …"],
   ["CALM","Let's focus on what we can change.","Moves forward.","Skupmy się na tym, co możemy zmienić."],
   ["CALM","I'd like us to find a solution together.","Collaborative.","Chciałbym/chciałabym, żebyśmy razem znaleźli rozwiązanie."],
   ["AGREE","What would a good outcome look like for you?","Asks about their goal.","Jak wyglądałoby dla Ciebie dobre rozwiązanie?"],
   ["AGREE","Let's agree on the next steps and review in two weeks.","Clear follow-up.","Ustalmy kolejne kroki i wróćmy do tego za dwa tygodnie."]]]],
  mc:[["A gentle opening:","I wanted to talk to you about something that's been on my mind.","We have a big problem with you.","Sit down. You're in trouble.",0],
   ["A neutral observation:","I've noticed that the last three reports were late.","You're always late with everything.","You obviously don't care.",0],
   ["You invite their side of the story:","Help me understand what's been happening.","Explain yourself!","No excuses, please.",0],
   ["You reflect their emotion:","It sounds like you're feeling overloaded.","You're too emotional.","Don't be upset.",0],
   ["You move the talk forward:","Let's focus on what we can change.","Let's talk more about your mistakes.","Whose fault was it?",0],
   ["Delivering bad news respectfully:","I'm afraid I have some bad news, and I wanted you to hear it from me first.","FYI, your project is cancelled.","Didn't anyone tell you?",0],
   ["You ask about their goal:","What would a good outcome look like for you?","What do you want, more money?","You decide nothing.",0],
   ["A clear follow-up:","Let's agree on the next steps and review in two weeks.","Let's see what happens.","Just fix it somehow.",0]],
  bank:{h:"Complete the conversation",text:"Manager: Tomek, {this isn't an easy conversation, but it's an important one}. {I've noticed that} you've missed the last two team meetings, and {I'm concerned that} the project is falling behind.\nTomek: Yes… it's been a hard month.\nManager: {Help me understand what's been happening}.\nTomek: I'm working on three projects at once.\nManager: {It sounds like you're feeling} overloaded. {Let's focus on what we can change}. {What would a good outcome look like for you}?\nTomek: Maybe someone else could take one project.\nManager: OK. {I'd like us to find a solution together}. {Let's agree on the next steps and review in two weeks}.",extra:["You're always late"]},
  task:{kind:"speak",h:"Hold a difficult conversation",intro:"A good team member has missed several deadlines. Record what you say as their manager — opening, listening and agreeing on next steps.",
   steps:[["Open respectfully","“This isn't an easy conversation, but it's an important one.”"],["Describe the issue (SBI)","“I've noticed that… The effect of that was…”"],["Invite their side","“Help me understand what's been happening.”"],["Reflect and refocus","“It sounds like you're feeling… Let's focus on what we can change.”"],["Agree next steps","“What support do you need from me? Let's review in two weeks.”"]],
   check:["I described behaviour, not personality.","I didn't use 'always' or 'never'.","I asked at least two open questions.","I reflected the other person's feelings.","We ended with concrete next steps and a review date."]}}
 ]},

/* ================= C1 · 12 Interviews and Career Moves ================= */
{id:"bz12",level:"C1",title:"Interviews and Career Moves",sub:"Talking about your experience and strengths, answering tough questions with STAR, and negotiating an offer.",subPl:"Mówienie o doświadczeniu i mocnych stronach, trudne pytania metodą STAR, negocjowanie oferty.",
 lessons:[
 {t:"Experience and strengths",intro:"Present your career story with confidence and the right tenses.",
  groups:[["Your career story",[
   ["STORY","I've been working in … for … years.","Present perfect continuous for ongoing experience.","Pracuję w … od … lat."],
   ["STORY","Before that, I spent three years at …","Past simple for finished jobs.","Wcześniej spędziłem/spędziłam trzy lata w …"],
   ["STORY","My current role involves …","+ -ing: involves managing …","Moja obecna rola obejmuje …"],
   ["ACHIEVE","One of my key achievements was …","Highlights a result.","Jednym z moich kluczowych osiągnięć było …"],
   ["ACHIEVE","I was responsible for increasing … by …","Quantified result.","Odpowiadałem/odpowiadałam za zwiększenie … o …"],
   ["MOTIVE","I'm looking for a role where I can …","Explains why you are applying.","Szukam stanowiska, w którym mogę …"]]],
  ["Strengths and weaknesses",[
   ["STRENGTH","I'd say my main strength is …","Natural, confident.","Powiedziałbym/powiedziałabym, że moją główną mocną stroną jest …"],
   ["STRENGTH","I have a proven track record in …","Evidence of success.","Mam udokumentowane sukcesy w …"],
   ["STRENGTH","I'm particularly good at …","+ -ing.","Szczególnie dobrze radzę sobie z …"],
   ["WEAKNESS","Something I've been working on is …","Turns a weakness into growth.","Coś, nad czym pracuję, to …"],
   ["WEAKNESS","In the past I tended to …, so now I …","Shows learning.","W przeszłości miałem/miałam tendencję do …, więc teraz …"],
   ["FIT","What attracted me to this company is …","Shows research.","W tej firmie przyciągnęło mnie …"]]]],
  note:{h:"Tenses for your career",html:`<table><tr><th>Tense</th><th>Use</th><th>Example</th></tr><tr><td>present perfect continuous</td><td>still doing it</td><td>I've been working as a team leader since 2021.</td></tr><tr><td>present perfect</td><td>experience, no date</td><td>I've managed budgets of up to €2m.</td></tr><tr><td>past simple</td><td>finished, with a time</td><td>In 2019 I joined ING.</td></tr></table><p class="no">✗ I work here since 2021.</p><p class="ok">✓ I've been working here since 2021.</p>`},
  mc:[["Which is correct?","I've been working as an analyst since 2020.","I work as an analyst since 2020.","I am working as an analyst since 2020.",0],
   ["A finished job with a date:","In 2018 I joined a start-up in Berlin.","In 2018 I have joined a start-up.","Since 2018 I joined a start-up.",0],
   ["A quantified achievement:","I was responsible for increasing online sales by 35%.","I did sales good.","Sales were big because of me, I think.",0],
   ["A confident strength:","I'd say my main strength is solving complex problems under pressure.","I'm perfect.","I don't have weaknesses or strengths.",0],
   ["A good answer about a weakness:","In the past I tended to take on too much, so now I prioritise with my manager weekly.","I work too hard.","I have no weaknesses.",0],
   ["Which is correct?","My current role involves managing a team of eight.","My current role involves to manage a team.","My current role is involve managing.",0],
   ["You show you researched the company:","What attracted me to this company is your focus on sustainability.","I need a job.","My friend works here.",0],
   ["Evidence of repeated success:","I have a proven track record in launching new products.","I tried to launch products.","Products are my hobby.",0]],
  bank:{h:"Complete the 'Tell me about yourself' answer",text:"{I've been working in} logistics {for} eight years. {Before that, I spent three years at} DHL as a planner. {My current role involves} managing a team of twelve and a budget of €3m. {One of my key achievements was} a new routing system — {I was responsible for increasing} on-time delivery {by} 20%. {I'd say my main strength is} turning data into decisions. {Something I've been working on is} delegating more. {I'm looking for a role where I can} lead a bigger, international team, and {what attracted me to this company is} your expansion in Scandinavia.",extra:["I work here since","I'm perfect"]}},
 {t:"Tough questions and the STAR method",intro:"Answer behavioural questions with structure, and buy time when a question is hard.",
  groups:[["STAR answers",[
   ["S","The situation was that …","Situation: context.","Sytuacja wyglądała tak, że …"],
   ["T","My task was to …","Task: your responsibility.","Moim zadaniem było …"],
   ["A","What I did was …","Action: what YOU did (use 'I').","To, co zrobiłem/zrobiłam, to …"],
   ["A","First I …, then I …","Sequence of actions.","Najpierw …, potem …"],
   ["R","As a result, …","Result: the outcome.","W rezultacie …"],
   ["R","What I learned from that was …","Reflection — strong ending.","Wyniosłem/wyniosłam z tego, że …"]]],
  ["Handling difficult questions",[
   ["TIME","That's an interesting question — let me think for a moment.","Buys time naturally.","Ciekawe pytanie — pozwólcie, że się chwilę zastanowię."],
   ["CLARIFY","Do you mean … or …?","Clarifies a vague question.","Czy chodzi o … czy o …?"],
   ["HONEST","I haven't had direct experience of that, but …","Honest + transfer skills.","Nie miałem/miałam bezpośredniego doświadczenia z tym, ale …"],
   ["GAP","I took a year out to …, during which I …","Explains a CV gap positively.","Wziąłem/wzięłam rok przerwy, aby …, w tym czasie …"],
   ["LEAVE","I'm looking for new challenges that my current role can't offer.","Why you're leaving — no criticism.","Szukam nowych wyzwań, których obecna rola nie oferuje."],
   ["FUTURE","In five years, I'd like to be …","Career goals.","Za pięć lat chciałbym/chciałabym być …"]]]],
  note:{h:"STAR in one example",html:`<p><b>Question:</b> “Tell me about a time you dealt with a difficult client.”</p><p><b>S:</b> The situation was that a key client threatened to cancel after a delivery error.</p><p><b>T:</b> My task was to keep the account.</p><p><b>A:</b> What I did was call them the same day, take responsibility and offer a weekly status report.</p><p><b>R:</b> As a result, they renewed for two years. What I learned from that was to communicate early.</p><div class="bz-box warn">Spend most of the time on <b>A</b> and <b>R</b>. Say <b>I</b>, not <b>we</b>, for your own actions.</div>`},
  mc:[["Which part of STAR is 'what YOU did'?","Action","Situation","Task",0],
   ["A strong ending for a STAR answer:","What I learned from that was to involve the client earlier.","That's all.","So yeah.",0],
   ["You need a few seconds to think:","That's an interesting question — let me think for a moment.","Ehhh… no idea.","Next question, please.",0],
   ["The question is vague:","Do you mean conflicts with colleagues or with clients?","Your question is unclear.","I don't understand English.",0],
   ["Why are you leaving your current job?","I'm looking for new challenges that my current role can't offer.","My boss is terrible.","They don't pay me enough, and the team is lazy.",0],
   ["You lack the exact experience:","I haven't had direct experience of that, but I've managed something similar in…","No, never.","I can do anything, no problem.",0],
   ["Explaining a gap in your CV:","I took a year out to travel, during which I learned Spanish.","I did nothing for a year.","Don't ask about that.",0],
   ["In STAR, use … for your own actions:","I","we","they",0]],
  bank:{h:"Complete the STAR answer",text:"Q: Tell me about a time you had to meet a very tight deadline.\nA: {The situation was that} our biggest client moved their launch forward by two weeks. {My task was to} deliver the full campaign in ten days instead of 24. {What I did was} split the work into daily goals. {First I} met the team to agree priorities, {then I} cut two features the client didn't need. {As a result}, we delivered on time and the client increased their budget. {What I learned from that was} to say no to small things to protect the big ones.",extra:["We did","So yeah"]}},
 {t:"Questions, offers and salary",intro:"Ask smart questions at the end of an interview and negotiate an offer professionally.",
  groups:[["Your questions",[
   ["ASK","Could you tell me more about the team I'd be working with?","Shows real interest.","Czy może Pan/Pani powiedzieć więcej o zespole, z którym bym pracował/a?"],
   ["ASK","What would success look like in the first six months?","Smart, results-focused.","Jak wyglądałby sukces w pierwszych sześciu miesiącach?"],
   ["ASK","What are the biggest challenges facing the team right now?","Shows strategic thinking.","Jakie są obecnie największe wyzwania zespołu?"],
   ["ASK","What are the next steps in the process?","End of the interview.","Jakie są kolejne etapy rekrutacji?"],
   ["THANK","Thank you for your time — I'm very interested in the role.","Final line.","Dziękuję za poświęcony czas — jestem bardzo zainteresowany/a tym stanowiskiem."]]],
  ["Negotiating the offer",[
   ["OFFER","Thank you for the offer — I'm delighted.","Positive first reaction.","Dziękuję za ofertę — bardzo się cieszę."],
   ["OFFER","Could I have a couple of days to consider it?","Buys time.","Czy mogę mieć kilka dni na zastanowienie?"],
   ["SALARY","Based on my experience and the market rate, I was expecting something closer to …","Counter-offer with reasons.","Biorąc pod uwagę moje doświadczenie i stawki rynkowe, oczekiwałem/am kwoty bliższej …"],
   ["SALARY","Is there any flexibility on the base salary?","Soft question.","Czy jest jakaś elastyczność w kwestii wynagrodzenia podstawowego?"],
   ["PACKAGE","If the salary is fixed, could we look at …?","Negotiates the package.","Jeśli pensja jest stała, czy moglibyśmy rozważyć …?"],
   ["ACCEPT","I'm happy to accept the offer.","Accepts.","Z przyjemnością przyjmuję ofertę."]]]],
  note:{h:"Package vocabulary",html:`<table><tr><th>Term</th><th>Polish</th></tr><tr><td>base salary</td><td>wynagrodzenie podstawowe</td></tr><tr><td>gross / net</td><td>brutto / netto</td></tr><tr><td>bonus</td><td>premia</td></tr><tr><td>benefits / perks</td><td>świadczenia / benefity</td></tr><tr><td>notice period</td><td>okres wypowiedzenia</td></tr><tr><td>B2B contract / employment contract</td><td>umowa B2B / umowa o pracę</td></tr><tr><td>remote / hybrid</td><td>zdalnie / hybrydowo</td></tr></table>`},
  mc:[["A smart question at the end of an interview:","What would success look like in the first six months?","How many holidays do I get?","Do you check what time I arrive?",0],
   ["You want to know about the process:","What are the next steps in the process?","When do I start?","Did I get the job?",0],
   ["You receive an offer but need time:","Thank you for the offer — could I have a couple of days to consider it?","Maybe. I'll see.","I'll think, bye.",0],
   ["A professional counter-offer:","Based on my experience and the market rate, I was expecting something closer to 18,000.","That's too little, give me more.","Other companies pay more, so pay me.",0],
   ["The salary is fixed. You negotiate other things:","If the salary is fixed, could we look at an extra day of remote work?","Then I don't want it.","OK, nothing then.",0],
   ["Time you must work after resigning:","notice period","base salary","bonus",0],
   ["A soft question about money:","Is there any flexibility on the base salary?","Can you pay more or not?","Money is low.",0],
   ["You accept:","I'm happy to accept the offer.","I take it, finally.","Yes OK I agree to accept to the offer.",0]],
  bank:{h:"Complete the offer call",text:"HR: We'd like to offer you the position, with a base salary of 15,000 gross.\nYou: {Thank you for the offer — I'm delighted}. {Could I have a couple of days to consider it}?\nHR: Of course.\n— Two days later —\nYou: {Based on my experience and the market rate, I was expecting something closer to} 17,000. {Is there any flexibility on the base salary}?\nHR: The salary band is fixed at 15,500, I'm afraid.\nYou: I understand. {If the salary is fixed, could we look at} a performance bonus and two days of remote work?\nHR: Yes, we can do that.\nYou: Great. {I'm happy to accept the offer}.",extra:["give me more"]},
  task:{kind:"speak",h:"Mock interview: three answers",intro:"Record your answers to three classic questions. Use the right tenses and the STAR structure.",
   steps:[["“Tell me about yourself.”","Present perfect continuous → past experience → key achievement → why this role."],["“What's your main strength — and a weakness?”","“I'd say my main strength is… Something I've been working on is…”"],["“Tell me about a time you solved a difficult problem.”","Situation → Task → Action → Result → What I learned."],["Your question to them","“What would success look like in the first six months?”"]],
   topics:["Your real job or the job you want next","A team leader role in an international company","A first job after university"],
   check:["I used 'I've been working…' for my current job.","I gave at least one number in an achievement.","My weakness answer shows how I'm improving.","My STAR answer spent most time on Action and Result.","I used 'I', not 'we', for my own actions.","I asked one smart question at the end."]}}
 ]}
);
